function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MyCalendar' || args[0].length !== 0) return 'Start with MyCalendar and no arguments.';
  if (operations.length - 1 > 1000) return 'At most 1000 calls to book.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'book') return 'Only book can follow the constructor.';
    const [startTime, endTime] = args[i];
    if (args[i].length !== 2 || !Number.isInteger(startTime) || !Number.isInteger(endTime)) return 'book takes two whole numbers.';
    if (startTime < 0 || startTime >= endTime || endTime > 1000000000) return 'Each booking needs 0 <= startTime < endTime <= 10^9.';
  }
  return null;
}

