class MyCalendar {
  constructor() {
    this.bookings = [];
  }

  book(startTime, endTime) {
    const bookings = this.bookings;
    let left = 0;
    let right = bookings.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (bookings[mid][0] < startTime) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    if (left < bookings.length && bookings[left][0] < endTime) {
      return false;
    }
    if (left > 0 && bookings[left - 1][1] > startTime) {
      return false;
    }
    bookings.splice(left, 0, [startTime, endTime]);
    return true;
  }
}

