function generate(rand, size) {
  const operations = ['MyCalendar'];
  const args = [[]];
  const LIMIT = 1000000000;
  if (size === 'small') {
    const calls = 1 + Math.floor(rand() * 14);
    const top = rand() < 0.8 ? 30 : LIMIT;
    for (let i = 0; i < calls; i++) {
      const length = 1 + Math.floor(rand() * (top === 30 ? 8 : 300000000));
      const start = Math.floor(rand() * (top - length + 1));
      operations.push('book');
      args.push([start, start + length]);
    }
    return [operations, args];
  }
  const grid = rand() < 0.5;
  for (let i = 0; i < 499; i++) {
    let start, end;
    if (grid) {
      const cell = 2000000;
      const first = Math.floor(rand() * 499);
      const span = 1 + Math.floor(rand() * 3);
      start = first * cell;
      end = Math.min(LIMIT, (first + span) * cell);
    } else {
      const length = 1 + Math.floor(rand() * rand() * 4000000);
      start = Math.floor(rand() * (LIMIT - length + 1));
      end = start + length;
    }
    operations.push('book');
    args.push([start, end]);
  }
  return [operations, args];
}
